import { AsyncPipe, NgClass, NgIf } from '@angular/common';
import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ComponentRef,
  ElementRef,
  HostListener,
  Input,
  OnDestroy,
  OnInit,
  Optional,
  ViewChild,
  inject,
} from '@angular/core';
import {
  FormsModule,
  ReactiveFormsModule,
  UntypedFormControl,
  UntypedFormGroup,
} from '@angular/forms';
import {
  ActiveCartFacade,
  Cart,
  CartConfig,
  CartItemComponentOptions,
  CartOutlets,
  CartUiEventAddToCart,
} from '@spartacus/cart/base/root';
import {
  CmsAddToCartComponent,
  EventService,
  Product,
  ProductAvailabilityService,
  ProductCatalogService,
  ProductScope,
  ProductTypes,
  TranslatePipe,
  isNotNullable,
} from '@spartacus/core';
import {
  CmsComponentData,
  CurrentProductService,
  ICON_TYPE,
  IconComponent,
  ItemCounterComponent,
  OutletDirective,
  ProductListItemContext,
} from '@spartacus/storefront';
import { Observable, Subscription } from 'rxjs';
import { filter, map, take } from 'rxjs/operators';

@Component({
  selector: 'cx-add-to-cart',
  templateUrl: './add-to-cart.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    NgIf,
    FormsModule,
    ReactiveFormsModule,
    ItemCounterComponent,
    OutletDirective,
    NgClass,
    IconComponent,
    AsyncPipe,
    TranslatePipe,
  ],
})
export class AddToCartComponent implements OnInit, OnDestroy {
  @Input() productCode: string;
  @Input() showQuantity = true;
  @Input() options: CartItemComponentOptions;
  @Input() pickupStore: string | undefined;
  @Input() savedCart: Cart | undefined;

  /**
   * As long as we do not support #5026, we require product input, as we need
   *  a reference to the product model to fetch the stock data.
   */
  @Input() product: Product;

  /**
   * Element responsible for opening the modal. The reference is used to refocus the modal after it closes.
   */
  @ViewChild('addToCartDialogTriggerEl') addToCartDialogTriggerEl: ElementRef;

  maxQuantity: number;

  disabled: boolean = false;

  hasStock: boolean = false;
  inventoryThreshold: boolean = false;

  showInventory$: Observable<boolean | undefined> | undefined =
    this.component?.data$.pipe(map((data) => data.inventoryDisplay));
  unavailable: boolean = false;

  quantity = 1;

  subscription = new Subscription();

  addToCartForm = new UntypedFormGroup({
    quantity: new UntypedFormControl(1, { updateOn: 'blur' }),
  });

  readonly CartOutlets = CartOutlets;

  pickupOptionCompRef: any;

  iconTypes = ICON_TYPE;

  private productAvailabilityService = inject(ProductAvailabilityService);
  protected productCatalogService = inject(ProductCatalogService);
  protected realTimeStockEnabled =
    !!inject(CartConfig).cart?.showRealTimeStockInPDP?.enabled;

  /**
   * We disable the dialog launch on quantity input,
   * as it causes an unexpected change of context.
   * The expectation is only for the quantity to get updated in the Qty field.
   */
  @HostListener('document:keydown', ['$event'])
  handleKeyboardEvent(event: KeyboardEvent) {
    const eventTarget = event.target as HTMLElement;
    const isQuantityInput =
      eventTarget.ariaLabel === 'Quantity' && eventTarget.tagName === 'INPUT';
    if (event.key === 'Enter' && isQuantityInput) {
      event.preventDefault();
    }
  }

  constructor(
    protected currentProductService: CurrentProductService,
    protected cd: ChangeDetectorRef,
    protected activeCartService: ActiveCartFacade,
    protected component: CmsComponentData<CmsAddToCartComponent>,
    protected eventService: EventService,
    @Optional() protected productListItemContext?: ProductListItemContext
  ) {}

  ngOnInit() {
    if (this.product) {
      this.productCode = this.product.code ?? '';
      this.setStockInfo(this.product);
      this.unavailable = !this.productCatalogService.isProductInCatalog(
        this.product
      );
    } else if (this.productCode) {
      // force hasStock and quantity for the time being, as we do not have more info:
      this.quantity = 1;
      this.hasStock = true;
      this.cd.markForCheck();
    } else {
      let product$: Observable<Product | null>;
      if (this.productListItemContext) {
        product$ = this.productListItemContext.product$;
      } else if (this.realTimeStockEnabled) {
        product$ = this.currentProductService.getProduct([
          ProductScope.UNIT,
          ProductScope.DETAILS,
        ]);
      } else {
        product$ = this.currentProductService.getProduct();
      }
      this.subscription.add(
        product$.pipe(filter(isNotNullable)).subscribe((product) => {
          this.productCode = product.code ?? '';
          this.product = product;
          this.setStockInfo(product);
          this.unavailable =
            !this.productCatalogService.isProductInCatalog(product);
        })
      );
    }
  }

  protected setStockInfo(product: Product): void {
    this.quantity = 1;

    this.addToCartForm.controls['quantity'].setValue(1);
    this.inventoryThreshold = product.stock?.isValueRounded ?? false;
    if (this.productListItemContext) {
      this.showQuantity = false;
    }

    if (this.realTimeStockEnabled && product.sapUnit?.sapCode) {
      this.productAvailabilityService
        .getRealTimeStock(this.productCode, product.sapUnit?.sapCode)
        .pipe(take(1))
        .subscribe(({ quantity, status }) => {
          this.maxQuantity = Number(quantity);
          this.hasStock = Boolean(status && status !== 'OUT_OF_STOCK');
          this.cd.markForCheck();
        });
    } else {
      this.hasStock = Boolean(product.stock?.stockLevelStatus !== 'outOfStock');
      if (this.hasStock && product.stock?.stockLevel) {
        this.maxQuantity = product.stock.stockLevel;
      }
      this.cd.markForCheck();
    }
  }

  /**
   * In specific scenarios, we need to omit displaying the stock level or append a plus to the value.
   * When backoffice forces a product to be in stock, omit showing the stock level.
   * When product stock level is limited by a threshold value, append '+' at the end.
   * When out of stock, display no numerical value.
   */
  getInventory(): string {
    if (
      this.hasStock &&
      this.product.productTypes !== ProductTypes.SUBSCRIPTION
    ) {
      const quantityDisplay = this.maxQuantity
        ? this.maxQuantity.toString()
        : '';
      return this.inventoryThreshold ? quantityDisplay + '+' : quantityDisplay;
    } else {
      return '';
    }
  }

  updateCount(value: number): void {
    this.quantity = value;
  }

  addToCart() {
    let quantity = 0;

    if (this.savedCart) {
      quantity = this.getQuantityFromSavedCart(this.productCode);
    } else {
      quantity = this.addToCartForm.get('quantity')?.value;
    }

    if (!this.productCode || quantity <= 0) {
      return;
    }

    if (this.pickupOptionCompRef instanceof ComponentRef) {
      this.pickupOptionCompRef.instance.intendedPickupLocation$
        .pipe(take(1))
        .subscribe((intendedPickupLocation: any) => {
          this.pickupStore =
            intendedPickupLocation?.pickupOption === 'pickup'
              ? intendedPickupLocation.name
              : undefined;
        });
    }

    this.activeCartService
      .getEntries()
      .pipe(take(1))
      .subscribe((cartEntries) => {
        this.activeCartService.addEntry(
          this.productCode,
          quantity,
          this.pickupStore
        );

        // A CartUiEventAddToCart is dispatched.  This event is intended for the UI
        // responsible to provide feedback about what was added to the cart, like
        // the added to cart dialog.
        //
        // Because we call activeCartService.getEntries() before, we can be sure the
        // cart library is loaded already and that the event listener exists.
        this.eventService.dispatch(
          this.createCartUiEventAddToCart(
            this.productCode,
            quantity,
            cartEntries.length,
            this.pickupStore
          )
        );
      });
  }

  protected createCartUiEventAddToCart(
    productCode: string,
    quantity: number,
    numberOfEntriesBeforeAdd: number,
    storeName?: string
  ) {
    const newEvent = new CartUiEventAddToCart();
    newEvent.productCode = productCode;
    newEvent.quantity = quantity;
    newEvent.numberOfEntriesBeforeAdd = numberOfEntriesBeforeAdd;
    newEvent.pickupStoreName = storeName;
    newEvent.triggerElementRef = this.addToCartDialogTriggerEl;
    return newEvent;
  }

  onPickupOptionsCompLoaded() {
    if (this.pickupOptionCompRef instanceof ComponentRef) {
      this.subscription.add(
        this.pickupOptionCompRef.instance.intendedPickupChange.subscribe(
          (
            intendedPickupLocation:
              | { pickupOption?: 'pickup' | 'delivery'; displayName?: string }
              | undefined
          ) => {
            this.disabled =
              intendedPickupLocation?.pickupOption === 'pickup' &&
              !intendedPickupLocation.displayName;
          }
        )
      );
    }
  }

  protected getQuantityFromSavedCart(productCode: string): number {
    return (
      this.savedCart?.entries?.find((e) => e?.product?.code === productCode)
        ?.quantity ?? 0
    );
  }

  ngOnDestroy() {
    this.subscription.unsubscribe();
  }
}
